# Bash completion for copier
# Generated by plumbum.cli.Application

_copier_completion() {
    local cur="${COMP_WORDS[COMP_CWORD]}"
    local prev="${COMP_WORDS[COMP_CWORD-1]}"
    local words="${COMP_WORDS[@]}"

    COMPREPLY=()

    # Static completions for switches and subcommands
    local switches="--help-all -h --help -v --version --completions"
    local subcommands="copy recopy update check-update"

    # If previous word is a switch that takes an argument, let the app handle it
    case "$prev" in
        --completions)
            COMPREPLY=( $(compgen -W "$(copier --complete $cur 2>/dev/null)" -- "$cur") )
            return
            ;;
        *)
            ;;
    esac

    # Complete switches and subcommands
    if [[ "$cur" == -* ]]; then
        COMPREPLY=( $(compgen -W "$switches" -- "$cur") )
    else
        COMPREPLY=( $(compgen -W "$subcommands" -- "$cur") )
    fi
}

complete -F _copier_completion copier

